examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space4) {
    MonarchStepper(steps, current: step, furthest: step)
    switch step {
    case 0:
        Text({{title}})
            .monarchTextStyle(.heading)
            .accessibilityAddTraits(.isHeader)
        Text({{description}})
            .monarchTextStyle(.body)
            .foregroundStyle(theme.colors.textMuted)
        MonarchFileUpload(allowedContentTypes: [.commaSeparatedText], maxSize: {{maxSize}}, maxFiles: 1,
            labels: MonarchFileUploadLabels(
                title: "Drag and drop a CSV file here",
                browse: "Choose file",
                limits: { _, _ in
                    "Up to \(ByteCountFormatter.string(fromByteCount: {{maxSize}}, countStyle: .binary)) each · 1 file max"
                }
            )
        ) { files, _ in
            guard let file = files.first else { return }
            // The file may hold {{maxRows|raw}} data rows: the first line names the columns.
            if Self.dataRows(in: file) <= {{maxRows}} {
                hasTooManyRows = false
                step = 1
            } else {
                hasTooManyRows = true
            }
        }
        if hasTooManyRows {
            MonarchInlineNotice("The file has more than \({{maxRows}}) rows.", tone: .danger)
        }
        if let template = URL(string: "https://example.com/contacts-template.csv") {
            Link({{template}}, destination: template)
                .buttonStyle(.monarchLink(.standalone))
        }
    case 1:
        MonarchColumnMapping(Self.sources, mapping: $mapping, fields: Self.fields)
            .frame(height: 420)
    case 2:
        MonarchPreviewRows(
            "Preview of contacts.csv",
            rows: [
                MonarchPreviewRow(row: 1, values: ["email": "ada@example.com", "name": "Ada Moss"]),
                MonarchPreviewRow(
                    row: 2,
                    values: ["email": "bea@example.com", "name": ""],
                    errors: [MonarchPreviewRowIssue("Name is required", field: "Name")]
                ),
            ],
            columns: Self.fields.map { MonarchPreviewRowsColumn($0.label, id: $0.id) }
        )
        ProgressView("Importing 1 row…", value: 0.5)
            .progressViewStyle(.monarchLinear)
    default:
        MonarchInlineNotice("1 created, 1 skipped.", tone: .success)
    }
    if step > 0 {
        HStack {
            if step < 3 {
                MonarchButton("Back") { step -= 1 }
            }
            Spacer(minLength: 0)
            if step < 3 {
                MonarchButton(step == 2 ? "Import 1 row" : "Continue", variant: .primary) { step += 1 }
                    .disabled(step == 1 && !MonarchColumnMapping.issues(mapping, fields: Self.fields).missing.isEmpty)
            }
        }
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var step = 0
@State private var hasTooManyRows = false

/// The data rows of a CSV file: its lines after the header.
private static func dataRows(in file: MonarchFileUploadFile) -> Int {
    let didStart = file.url.startAccessingSecurityScopedResource()
    defer { if didStart { file.url.stopAccessingSecurityScopedResource() } }
    guard let text = try? String(contentsOf: file.url, encoding: .utf8) else { return 0 }
    return max(0, text.split(whereSeparator: \.isNewline).count - 1)
}
private static let sources = [
    MonarchColumnMappingSource("E-mail", samples: ["ada@example.com", "bea@example.com"]),
    MonarchColumnMappingSource("Full name", samples: ["Ada Moss", ""]),
]
private static let fields = [
    MonarchColumnMappingField(id: "email", label: "Email", isRequired: true, aliases: ["E-mail"]),
    MonarchColumnMappingField(id: "name", label: "Name", isRequired: true, aliases: ["Full name"]),
]
@State private var mapping = MonarchColumnMapping.mapping(
    from: MonarchColumnMapping.suggest(Self.sources, fields: Self.fields)
)
private let steps = [
    MonarchStepperStep(id: "upload", label: {{steps.0}}),
    MonarchStepperStep(id: "map", label: {{steps.1}}),
    MonarchStepperStep(id: "preview", label: {{steps.2}}),
    MonarchStepperStep(id: "results", label: {{steps.3}}),
]

